"use client";
import { partnerLinks } from "@/lib/partnerLinks";
import React from "react";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import {
  faHandHoldingDollar,
  faSackDollar,
} from "@fortawesome/free-solid-svg-icons";
import Destinations from "../destinations";

const earnTiers = [
  "30 € are defined for every operator when they register.",
  "Save 2% for 75.000 € up to 149.999 € booking.",
  "Save 5% for 150.000 € up to 299.999 € booking.",
  "Save 10% over 300.000 € and more booking.",
];

const faqs = [
  {
    q: "What are the ways to earn Travel Credits?",
    a: (
      <>
        <p className="tw-mt-0 tw-mb-3 tw-text-[14px] tw-leading-[1.7] tw-text-[#5d556c]">
          When you book with TravelShop Booking, you&apos;ll earn Travel Credits
          to use on future adventures. How does it work?
        </p>
        <ul className="tw-m-0 tw-pl-5 tw-space-y-1 tw-text-[14px] tw-text-[#5d556c]">
          {earnTiers.map((t) => (
            <li key={t}>{t}</li>
          ))}
        </ul>
        <p className="tw-mt-3 tw-mb-0 tw-text-[13px] tw-italic tw-text-[#6b6577]">
          (Currency depends on your booking currency: USD, AUD, £, ₹, €){" "}
          <a
            href="/terms-of-use"
            target="_blank"
            rel="noopener noreferrer"
            className="tw-font-semibold tw-text-[#854ec9]"
          >
            Full Terms &amp; Conditions
          </a>
        </p>
      </>
    ),
  },
  {
    q: "Where can I check my Travel Credits?",
    a: (
      <>
        <p className="tw-mt-0 tw-mb-3 tw-text-[14px] tw-leading-[1.7] tw-text-[#5d556c]">
          First, ensure you&apos;re logged into your TravelShop Booking account.
          Once signed in, there are several ways to check your Travel Credits.
        </p>
        <p className="tw-mt-0 tw-mb-0 tw-text-[14px] tw-leading-[1.7] tw-text-[#5d556c]">
          Visit the{" "}
          <a
            href={partnerLinks.login}
            target="_blank"
            rel="noopener noreferrer"
            className="tw-font-semibold tw-text-[#854ec9]"
          >
            My Account
          </a>{" "}
          section to see your current Travel Credits. You can also find them in
          the top header while browsing our website. On the booking page for
          your tour, you&apos;ll see how much your Travel Credits reduce the
          total cost!
        </p>
      </>
    ),
  },
  {
    q: "How can I use my Travel Credits?",
    a: (
      <>
        <p className="tw-mt-0 tw-mb-3 tw-text-[14px] tw-leading-[1.7] tw-text-[#5d556c]">
          Fantastic news! You can use your Travel Credits to book your next
          adventure with TravelShop Booking. After completing your first tour,
          your account will update to display the credits you&apos;ve earned in
          your booking currency (USD, EUR, etc.).
        </p>
        <p className="tw-mt-0 tw-mb-0 tw-text-[13px] tw-italic tw-text-[#6b6577]">
          *You can only use Travel Credits for up to 5% of the total booking
          value of any Travel Adventure. Credits cannot be combined with Member
          Savings or promo codes.
        </p>
      </>
    ),
  },
  {
    q: "What are the steps to apply Travel Credits?",
    a: (
      <p className="tw-m-0 tw-text-[14px] tw-leading-[1.7] tw-text-[#5d556c]">
        When you&apos;re ready, log in to your TravelShop Booking account and
        choose the tour you want to book. Apply your credits in the
        &apos;TravelShop Booking Savings&apos; section, then click &apos;Book
        Now&apos; to enjoy your savings! (Note: Travel Credits cannot be
        combined with other TravelShop Booking discounts.)
      </p>
    ),
  },
  {
    q: "What should I do if my Travel Credits are missing?",
    a: (
      <p className="tw-m-0 tw-text-[14px] tw-leading-[1.7] tw-text-[#5d556c]">
        Once you return from your tour, your earned Travel Credits will be added
        to your account. If they&apos;re not visible, contact us with your
        booking&apos;s itinerary number. We&apos;ll investigate and ensure any
        missing credits are added.
      </p>
    ),
  },
  {
    q: "Are Travel Credits redeemable for cash?",
    a: (
      <p className="tw-m-0 tw-text-[14px] tw-leading-[1.7] tw-text-[#5d556c]">
        Travel Credits are our way of saying thank you for booking with
        TravelShop Booking, so they cannot be converted into cash. We prefer to
        gift you with credits instead of a thank you card, helping you save on
        your next adventure with us!
      </p>
    ),
  },
  {
    q: "Are Travel Credits transferable to a friend?",
    a: (
      <p className="tw-m-0 tw-text-[14px] tw-leading-[1.7] tw-text-[#5d556c]">
        While Travel Credits cannot be transferred to a friend, the good news is
        they never expire! When you&apos;re ready to book your next amazing
        adventure with TravelShop Booking, your credits will be available to
        help you save.
      </p>
    ),
  },
  {
    q: "Do Travel Credits have an expiration date?",
    a: (
      <>
        <p className="tw-mt-0 tw-mb-3 tw-text-[14px] tw-leading-[1.7] tw-text-[#5d556c]">
          Your Travel Credits never expire! They&apos;ll remain in your
          TravelShop Booking account for life, ready to be used on your next
          adventure with us.
        </p>
        <p className="tw-mt-0 tw-mb-0 tw-text-[13px] tw-italic tw-text-[#6b6577]">
          *We reserve the right to update our loyalty program and Travel Credits
          at any time. For more details, please refer to the{" "}
          <a
            href="/terms-of-use"
            target="_blank"
            rel="noopener noreferrer"
            className="tw-font-semibold tw-text-[#854ec9]"
          >
            Terms &amp; Conditions
          </a>
          .
        </p>
      </>
    ),
  },
];

const Invite = () => {
  return (
    <main className="tw-font-display tw-bg-white">
      {/* Hero */}
      <section className="tw-relative tw-overflow-hidden">
        <div
          className="tw-absolute tw-inset-0 tw-bg-cover tw-bg-center"
          style={{ backgroundImage: "url('/images/friends.png')" }}
          aria-hidden="true"
        />
        <div
          className="tw-absolute tw-inset-0"
          style={{
            background:
              "linear-gradient(180deg, rgba(20,16,28,0.5) 0%, rgba(20,16,28,0.6) 55%, rgba(20,16,28,0.82) 100%)",
          }}
          aria-hidden="true"
        />
        <div className="tw-relative tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10 tw-py-24 md:tw-py-32">
          <div className="tw-max-w-[760px]">
            <span className="tw-inline-flex tw-items-center tw-gap-2 tw-rounded-full tw-bg-white/10 tw-border tw-border-solid tw-border-white/20 tw-px-4 tw-py-1.5 tw-text-[13px] tw-font-semibold tw-text-white tw-backdrop-blur">
              Rewards Program
            </span>
            <h1 className="tw-mt-5 tw-text-[clamp(32px,5vw,56px)] tw-font-bold tw-tracking-tight tw-leading-[1.05] tw-text-white tw-m-0">
              TravelShop Booking Reward Credits
            </h1>
            <p className="tw-mt-5 tw-mb-0 tw-text-[17px] tw-leading-[1.6] tw-text-white/85 tw-max-w-[60ch]">
              Earn Travel Credits with every booking and turn your loyalty into
              real savings on your next adventure.
            </p>
          </div>
        </div>
      </section>

      {/* Accumulate */}
      <section className="tw-py-12 md:tw-py-16">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-grid tw-grid-cols-1 lg:tw-grid-cols-[280px_1fr] tw-gap-8 lg:tw-gap-12 tw-items-center tw-rounded-3xl tw-bg-[#faf8ff] tw-border tw-border-solid tw-border-[#ebe7f0] tw-p-7 md:tw-p-10">
            <div className="tw-flex tw-items-center tw-justify-center">
              <div className="tw-flex tw-h-40 tw-w-40 tw-items-center tw-justify-center tw-rounded-full tw-bg-[#854ec9]/10 tw-text-[#854ec9]">
                <FontAwesomeIcon
                  icon={faHandHoldingDollar}
                  className="tw-text-7xl"
                />
              </div>
            </div>
            <div>
              <span className="tw-text-[13px] tw-font-semibold tw-uppercase tw-tracking-wider tw-text-[#854ec9]">
                Accumulate
              </span>
              <h2 className="tw-mt-2 tw-text-[clamp(22px,3vw,30px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
                How can you earn Travel Credits?
              </h2>
              <ol className="tw-mt-5 tw-space-y-4 tw-p-0 tw-m-0 tw-list-none">
                <li>
                  <p className="tw-m-0 tw-text-[15px] tw-font-bold tw-text-[#14101c]">
                    1. Book a tour
                  </p>
                  <ul className="tw-mt-2 tw-pl-5 tw-space-y-1 tw-text-[14px] tw-text-[#5d556c]">
                    {earnTiers.map((t) => (
                      <li key={t}>{t}</li>
                    ))}
                  </ul>
                  <p className="tw-mt-2 tw-mb-0 tw-text-[13px] tw-italic tw-text-[#6b6577]">
                    (Currency depends on your booking currency: USD, AUD, £, ₹,
                    €)
                  </p>
                </li>
                <li>
                  <p className="tw-m-0 tw-text-[15px] tw-font-bold tw-text-[#14101c]">
                    2. Go on the tour
                  </p>
                  <p className="tw-mt-1 tw-mb-0 tw-text-[14px] tw-text-[#5d556c]">
                    Time for an unforgettable adventure!
                  </p>
                </li>
                <li>
                  <p className="tw-m-0 tw-text-[15px] tw-font-bold tw-text-[#14101c]">
                    3. Return and receive your Travel Credits
                  </p>
                  <p className="tw-mt-1 tw-mb-0 tw-text-[14px] tw-text-[#5d556c]">
                    Get your Travel Credits when you come back. Use them
                    immediately or save up for bigger savings on future trips.
                  </p>
                </li>
              </ol>
              <p className="tw-mt-5 tw-mb-0 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
                It&apos;s our way of saying thank you! If you haven&apos;t
                already, log in or sign up to TravelShop Booking to check your
                Travel Credits.
              </p>
            </div>
          </div>
        </div>
      </section>

      {/* Use */}
      <section className="tw-pb-12 md:tw-pb-16">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-grid tw-grid-cols-1 lg:tw-grid-cols-[1fr_280px] tw-gap-8 lg:tw-gap-12 tw-items-center tw-rounded-3xl tw-bg-[#14101c] tw-p-7 md:tw-p-10">
            <div>
              <span className="tw-text-[13px] tw-font-semibold tw-uppercase tw-tracking-wider tw-text-[#b79be0]">
                Use &amp; Apply
              </span>
              <h2 className="tw-mt-2 tw-text-[clamp(22px,3vw,30px)] tw-font-bold tw-tracking-tight tw-text-white tw-m-0">
                Use &amp; Apply Travel Credits
              </h2>
              <p className="tw-mt-4 tw-text-[15px] tw-leading-[1.7] tw-text-white/80">
                To redeem your Travel Credits, choose the tour you want to book
                and go to the &apos;Book Now&apos; page. Apply your credits in
                the &apos;TravelShop Booking Savings&apos; section. After
                applying, just click &apos;Book Now&apos; and enjoy the savings
                on your tour!
              </p>
              <p className="tw-mt-4 tw-mb-0 tw-text-[13px] tw-italic tw-text-white/60">
                *Please be aware that you can only use Travel Credits for up to
                5% of the total booking value of any Travel Adventure. Travel
                Credits cannot be combined with Member Savings or promo codes.{" "}
                <a
                  href="/terms-of-use"
                  target="_blank"
                  rel="noopener noreferrer"
                  className="tw-font-semibold tw-text-[#b79be0]"
                >
                  Full Terms &amp; Conditions
                </a>
                .
              </p>
            </div>
            <div className="tw-flex tw-items-center tw-justify-center">
              <div className="tw-flex tw-h-40 tw-w-40 tw-items-center tw-justify-center tw-rounded-full tw-bg-white/10 tw-text-white">
                <FontAwesomeIcon icon={faSackDollar} className="tw-text-7xl" />
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* FAQ */}
      <section className="tw-py-12 md:tw-py-16 tw-bg-[#faf9fc]">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-text-center tw-mb-10">
            <h2 className="tw-text-[clamp(24px,3vw,34px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
              Frequently asked questions
            </h2>
          </div>
          <div className="tw-grid tw-grid-cols-1 md:tw-grid-cols-2 tw-gap-5 lg:tw-gap-6">
            {faqs.map((faq) => (
              <div
                key={faq.q}
                className="tw-rounded-2xl tw-bg-white tw-border tw-border-solid tw-border-[#ebe7f0] tw-p-6 hover:tw-border-[#d8d2e1] hover:tw-shadow-lg tw-transition-all tw-duration-200"
              >
                <h3 className="tw-text-[17px] tw-font-bold tw-text-[#14101c] tw-mt-0 tw-mb-3">
                  {faq.q}
                </h3>
                {faq.a}
              </div>
            ))}
          </div>
        </div>
      </section>

      <Destinations />
    </main>
  );
};

export default Invite;
